<?php
declare(strict_types=1);
require dirname(__DIR__, 2) . '/includes/bootstrap.php';
require_admin();
$counts = db()->query("SELECT status, COUNT(*) AS total FROM orders GROUP BY status")->fetchAll();
$recent = db()->query('SELECT id, public_code, customer_email, preferred_payment, amount_dzd, status, created_at FROM orders ORDER BY created_at DESC LIMIT 50')->fetchAll();
$totalOrders = (int)db()->query('SELECT COUNT(*) FROM orders')->fetchColumn();
$pendingProofs = (int)db()->query("SELECT COUNT(*) FROM payment_proofs WHERE review_status='PENDING'")->fetchColumn();
$paid = (float)db()->query("SELECT COALESCE(SUM(amount_dzd),0) FROM payments WHERE status='CONFIRMED'")->fetchColumn();
$labels=['NEW'=>'جديد','EMAIL_CHECK'=>'التحقق من البريد','ACTIVATION_PENDING'=>'بانتظار التفعيل','ACTIVATION_SENT'=>'تم إرسال الدعوة','CUSTOMER_CONFIRMED'=>'تم التأكيد','AWAITING_PAYMENT'=>'بانتظار الدفع','PAYMENT_SUBMITTED'=>'إثبات مرسل','PAYMENT_REVIEW'=>'مراجعة الدفع','PAID'=>'مدفوع','COMPLETED'=>'مكتمل','REJECTED'=>'مرفوض','CANCELLED'=>'ملغى','REFUND_PENDING'=>'استرداد قيد المراجعة','REFUNDED'=>'مسترد'];
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>لوحة الإدارة — Canva Pro DZ</title><link rel="stylesheet" href="/assets/app.css"></head><body><header class="topbar"><a class="brand" href="/">Canva <span>Pro DZ</span></a><nav><a href="/admin/settings.php">الإعدادات</a> <a href="/admin/logout.php">خروج</a></nav></header><main class="admin-wrap"><div class="admin-heading"><div><div class="eyebrow">لوحة التحكم</div><h1>إدارة الطلبات</h1></div><a class="button button-ghost" href="/admin/settings.php">إعدادات الموقع</a></div><div class="stats-grid"><div class="stat-card"><span>إجمالي الطلبات</span><strong><?= $totalOrders ?></strong></div><div class="stat-card"><span>إيصالات بانتظار المراجعة</span><strong><?= $pendingProofs ?></strong></div><div class="stat-card"><span>مدفوعات مؤكدة يدويًا</span><strong><?= e(number_format($paid,0)) ?> دج</strong></div></div><section class="status-summary"><h2>حسب الحالة</h2><div class="status-chips"><?php foreach($counts as $c): ?><span><?= e($labels[$c['status']] ?? $c['status']) ?>: <b><?= (int)$c['total'] ?></b></span><?php endforeach; ?></div></section><section class="table-card"><h2>أحدث الطلبات</h2><div class="table-scroll"><table><thead><tr><th>رقم</th><th>البريد</th><th>طريقة الدفع</th><th>المبلغ</th><th>الحالة</th><th>تحديث</th></tr></thead><tbody><?php foreach($recent as $o): ?><tr><td><?= e($o['public_code']) ?><small><?= e($o['created_at']) ?></small></td><td><?= e($o['customer_email']) ?></td><td><?= e($o['preferred_payment']) ?></td><td><?= e(number_format((float)$o['amount_dzd'],0)) ?> دج</td><td><?= e($labels[$o['status']] ?? $o['status']) ?></td><td><a href="/admin/order.php?id=<?= (int)$o['id'] ?>">فتح</a></td></tr><?php endforeach; ?><?php if(!$recent): ?><tr><td colspan="6">لا توجد طلبات حتى الآن.</td></tr><?php endif; ?></tbody></table></div></section></main></body></html>
